    function rocsparse_create_handle_typed(handle) result(create_handle)
      use, intrinsic :: iso_c_binding
      use hipfort_handles
      implicit none
      type(rocsparse_handle_t) :: handle
      integer(kind(rocsparse_status_success)) :: create_handle
      create_handle = rocsparse_create_handle_(handle%ptr)
    end function rocsparse_create_handle_typed

