    function rocsparse_get_git_rev_typed(handle, rev) result(get_git_rev)
      use, intrinsic :: iso_c_binding
      use hipfort_handles
      implicit none
      type(rocsparse_handle_t), value :: handle
      type(c_ptr), value :: rev
      integer(kind(rocsparse_status_success)) :: get_git_rev
      get_git_rev = rocsparse_get_git_rev_(handle%ptr, rev)
    end function rocsparse_get_git_rev_typed

    function rocsparse_get_git_rev_cstr(handle, rev) result(get_git_rev)
      use, intrinsic :: iso_c_binding
      implicit none
      type(c_ptr), value :: handle
      character(len=*), intent(out) :: rev
      integer(kind(rocsparse_status_success)) :: get_git_rev
      character(len=len(rev)+1, kind=c_char), target :: rev__c
      integer :: i__c
      rev__c = repeat(c_null_char, len(rev)+1)
      get_git_rev = rocsparse_get_git_rev_(handle, c_loc(rev__c))
      rev = ""
      do i__c = 1, len(rev)
        if (rev__c(i__c:i__c) == c_null_char) exit
        rev(i__c:i__c) = rev__c(i__c:i__c)
      end do
    end function rocsparse_get_git_rev_cstr

